# --- verbatim ../../mc83.py lines 21-21 sha256 3cbbfafb6dd92a5c7c6c462db11a97fed881464ed00a7aaf14c34b86326d657f
def phi(u): return np.exp(-0.5*u*u)/np.sqrt(2*np.pi)

# --- verbatim ../../mc83.py lines 22-27 sha256 79be398f25d0580d763cc089b311ed368cc2186bd9060a7f27f4e2b8bd34b9c2
def cfun(al,be):
    P=np.where(al>0, ndtr(-al)-ndtr(-be), ndtr(be)-ndtr(al))
    pa,pb=phi(al),phi(be)
    cev=1-P-al*pa+be*pb
    cno=np.where(P>1e-300,(pa-pb)**2/np.maximum(P,1e-300),0.0)
    return cev,cno

# --- verbatim ../../mc85_scan.py lines 13-15 sha256 6c26778f56705db4cefbf31a896cd965270161ac190a1b5ddf21476d7d20fa82
def regressors(a, chi, tt):
    ps = np.outer(tt, w)+chi
    return np.column_stack([np.full(len(tt), a0)]+[c for m in range(4) for c in (a[m]*np.cos(ps[:, m]), -a[m]*np.sin(ps[:, m]))])

